{
    size_t i;
    if (strlen(s) != n) return 0;
    for (i = 0; i < n; ++i) {
        if (!((s[i] >= '0' && s[i] <= '9') ||
              (s[i] >= 'a' && s[i] <= 'f'))) return 0;
    }
    return 1;
}

int xin_blob(const char *path, int *mark_out, char *stamp_out, size_t stamp_cap)
{
    FILE *fp;
    char line[256], slot[32], stamp[32], name[64], cls[32], extra;
    char *end;
    long mark, id;
    int rows = 0;

    if (path == NULL || stamp_out == NULL || stamp_cap < 9) return -1;
    fp = fopen(path, "r");
    if (fp == NULL) return -1;

    if (fgets(line, sizeof(line), fp) == NULL || strcmp(line, "REEL\n") != 0)
        goto bad;
    if (fgets(line, sizeof(line), fp) == NULL || strncmp(line, "MARK ", 5) != 0)
        goto bad;
    end = NULL;
    mark = strtol(line + 5, &end, 10);
    if (end == line + 5 || (*end != '\n' && *end != '\0')) goto bad;

    if (fgets(line, sizeof(line), fp) == NULL ||
