    if (fgets(line, sizeof(line), fp) == NULL ||
        sscanf(line, "STAMP %31s %c", stamp, &extra) != 1) goto bad;
    if (!lower_hex(slot, 4) || !lower_hex(stamp, 8) ||
        strncmp(slot, stamp, 4) != 0) goto bad;

    while (fgets(line, sizeof(line), fp) != NULL) {
        char *id_end;
        if (strncmp(line, "CALL ", 5) != 0 ||
            sscanf(line, "CALL %63s", name) != 1) goto bad;
        {
            char n2[64];
            int used = 0;
            if (sscanf(line, "CALL %63s %n", n2, &used) != 1 || used == 0) goto bad;
            id = strtol(line + used, &id_end, 10);
            if (id_end == line + used) goto bad;
            while (*id_end == ' ' || *id_end == '\t') ++id_end;
            if (sscanf(id_end, "%31s %c", cls, &extra) != 1 ||
                strcmp(cls, "live") != 0) goto bad;
        }
        (void)id;
        ++rows;
    }
    if (ferror(fp) || rows == 0) goto bad;
    fclose(fp);
    if (mark_out != NULL) *mark_out = (int)mark;
    memcpy(stamp_out, stamp, 9);
    return 0;

bad:
